using ll = long long;

const int N = 2e5 + 12;

int t, n, a[N], b[N];

int main()
{
    cin >> t;

    while( t -- )
    {
        cin >> n;

        for( int i = 1; i <= n; i ++ ) cin >> a[i];
        for( int i = 1; i <= n; i ++ ) cin >> b[i];

        int h = 0, sum = 0; ll ans = 0;
        sort(a + 1, a + n + 1); reverse(a + 1, a + n + 1);

        for( int i = 1; i <= n; i ++ )
        {
            while( h < n && sum + b[h + 1] <= i ) h ++, sum += b[h];
            ans = max(ans, a[i] * 1ll * h);
        }
        cout << ans << '\n';
    }
}

#include <bits/stdc++.h>

using namespace std;
const int maxn = 1'000'012;

int a[maxn], dp[maxn];
int n, q;

void solve() {
    cin >> n;

    for(int i = 1; i <= n; i++) {
        dp[i] = 1e9;
    }
    for(int i = 1; i <= n;i++) {
        cin >> a[i];
        dp[a[i]] = 1;
    }

    for(int i = 1; i <= n; i++) {
        for(int j = i; j <= n; j += i) {
            dp[j] = min(dp[j], dp[i] + dp[j / i]);
        }
    }

    for(int i = 1; i <= n; i++) {
        if(dp[i] == 1e9) {
            dp[i] = -1;
        }
        cout << dp[i] << " \n"[i == n];
    }
}

