using namespace std;

int t, n, ax, ay, bx, by;

signed main()
{
    cin >> t;

    while( t -- )
    {
        cin >> n >> ax >> ay >> bx >> by;
        vector <int> x(n + 5), y(n + 5), dp[2];

        dp[0] = dp[1] = vector <int> (n + 5, 0);
        map <int, int> mx, mn;

        mn[ax] = mx[ax] = ay;
        mn[bx] = mx[bx] = by;

        for( int i = 0; i < n; i ++ ) cin >> x[i];
        for( int i = 0; i < n; i ++ ) cin >> y[i];

        for( int i = 0; i < n; i ++ )
        {
            mx[x[i]] = max(mx[x[i]], y[i]);

            if(!mn.count(x[i])) mn[x[i]] = y[i];
            else mn[x[i]] = min(mn[x[i]], y[i]);
        }
        int lst = ax, cnt = 0;

        for( auto i : mx )
        {
            if( i.F == ax )
            {
                dp[0][0] = dp[1][0] = 0;
                continue;
            }
            int need = (i.F - lst) + (mx[i.F] - mn[i.F]);
            cnt ++;

            dp[0][cnt] = min(dp[0][cnt - 1] + abs(mx[i.F] - mn[lst]), dp[1][cnt - 1] + abs(mx[i.F] - mx[lst])) + need;
            dp[1][cnt] = min(dp[0][cnt - 1] + abs(mn[i.F] - mn[lst]), dp[1][cnt - 1] + abs(mn[i.F] - mx[lst])) + need;

            lst = i.F;
        }
        cout << dp[0][cnt] << '\n';
    }
}

#include <bits/stdc++.h>

#define sz(x) (int)(x.size())
#define pb push_back

using namespace std; 
const int N = 2e5 + 12;

int n, x, y, a, b;
vector <int> L, g[N];

void dfs( int v, int p = 0 )
{
	L.pb(v);

	for( auto to : g[v] )
	{
		if( to != p ) dfs(to, v);
	}
}
int ask( int a, int b )
{
	cout << "? " << a << ' ' << b << endl;
	int res; cin >> res; return res;
}
void solve()
{
	cin >> n;

	L.clear();
	for( int i = 1; i <= n; i ++ ) g[i].clear();

	for( int i = 1; i < n; i ++ )
	{
		cin >> a >> b;
		g[a].pb(b), g[b].pb(a);
	}
	dfs(1, 0);

	for( int i = 0; i < sz(L) - 1; i += 2 )
	{
		a = L[i], b = L[i + 1];

		if( ask(a, b) == 1 )
		{
			if( ask(a, a) == 1 ) cout << "! " << a << endl;
			else cout << "! " << b << endl;
			return;
		}
	}
	cout << "! " << L.back() << endl;
}
int main()
{
	int t; cin >> t;
	while( t -- ) solve();
}

#include <bits/stdc++.h>
#define ent '\n'
#define int long long

using namespace std;
const int maxn = 200012;
const int mod = 1e9 + 7;

int cnt[maxn], a[maxn], del[maxn];
int sz[maxn], bad[maxn], used[maxn];
vector<int> g[maxn], e[maxn], g2[maxn];
int n, m;

void dfs(int v, int p) {
    sz[v] = 1;
    used[v] = true;
    for(int to : g[v]) {
        if(to == p) {
            continue;
        }

        dfs(to, v);

        if(sz[to] % 2 == 0) {
            e[to].push_back(v);
            bad[v]++;
        }
        else {
            e[v].push_back(to);
            bad[to]++;
        }

        sz[v] += sz[to];
    }
}

void solve() {
    cin >> n;
    for(int i = 1; i <= n; i++) {
        cin >> a[i];
        a[i] %= 2;
        del[i] = cnt[i] = sz[i] = 0;
        bad[i] = used[i] = 0;
        g[i].clear();
        g2[i].clear();
        e[i].clear();
    }

    for(int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;

        cnt[u] += a[v], cnt[v] += a[u];

        if(a[u] && a[v]) {
            g[u].push_back(v);
            g[v].push_back(u);
        }
        if( a[u] && !a[v] ) g2[u].push_back(v);
        if( a[v] && !a[u] ) g2[v].push_back(u);
    }
    queue <int> q;

    for(int i = 1; i <= n; i++) {
        if(!cnt[i] && !a[i]) {
            cout << "NO\n";
            return;
        }
    }
    for(int i = 1; i <= n; i++) {
        if(a[i] && !used[i]) {
            dfs(i, 0);
            if(sz[i] % 2 == 0) {
                cout << "NO\n";
                return;
            }
        }
    }
    for(int i = 1; i <= n; i++) {
        if(a[i] && !bad[i]) {
            q.push(i);
        }
    }
    cout << "YES\n";
    int zero[n + 5];

    for( int i = 1; i <= n; i ++ ){
        zero[i] = 0;

        if( !a[i] && cnt[i] % 2 ) cout << i << ' ';
        else if( !a[i] ) zero[i] = 1;
    }
    while(!q.empty()) {
        int v = q.front(); q.pop();
        cout << v << ' ';
        for(int to : g2[v]){
            if(zero[to]) cout << to << ' ', zero[to] = 0;
        }
        for(int to : e[v]) {
            bad[to]--;
            if(bad[to] == 0) q.push(to);
        }
    }
    cout << ent;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int t = 1;
    cin >> t;
    while(t--) {
        solve();
    }
}

#include <bits/stdc++.h>

using namespace std;

const int N = 2e5 + 12;
const int inf = 1e9 + 1;

int n, x, y, a[N], dp[N], cnt[N], par[N];
vector <int> g[N], g2[N]; bool flag, used[N];
pair <int, int> must[N][3]; vector <int> ord;

void dfs( int v, int p = 0 )
{
	int s = 0, ok = 0, id = 0;
	par[v] = p; ord.push_back(v);

	for( auto to : g[v] )
	{
		if( to == p ) continue;

		dfs(to, v);
		if(!flag) return;

		if( dp[to] == 1 || dp[to] == 3 )
		{
			s ^= a[to];

			if( dp[to] == 3 && a[to] == 1 )
			{
				if( !ok )
				{
					ok = 1;
					id = to;
				}
			}
			if( dp[to] == 3 && id != to ) dp[to] = 1;
		}
	}
	if( !ok && s == a[v] && (s + a[p]) % 2 == a[v] )
	{
		flag = 0;
		return;
	}
	if( s != a[v] || ok )
	{
		if( s == a[v] ) must[v][1] = {id, 2};
		else if(ok) must[v][1] = {id, 1};

		dp[v] = 1;
	}
	s = (s + a[p]) % 2;

	if( s != a[v] || ok )
	{
		if( s == a[v] ) must[v][2] = {id, 2};
		else if(ok) must[v][2] = {id, 1};

		dp[v] += 2;
	}
}
void dfs2( int v, int tp )
{
	dp[v] = tp, used[v] = 1;
	pair <int, int> p = must[v][tp];
	if( p.first != 0 ) dfs2(p.first, p.second);
}
void solve()
{
	cin >> n;
	flag = 1;

	// dp[v] = 1, if p[v] before v
	// dp[v] = 2, if v before p[v]

	for( int i = 1; i <= n; i ++ )
	{
		cin >> a[i];
		a[i] %= 2;

		must[i][1] = must[i][2] = {0, 0};
		dp[i] = cnt[i] = used[i] = 0;
		g[i].clear(), g2[i].clear();
	}
	for( int i = 1; i < n; i ++ )
	{
		cin >> x >> y;

		g[x].push_back(y);
		g[y].push_back(x);
	}
	ord.clear();
	dfs(1);

	if( !flag )
	{
		cout << "No\n";
		return;
	}
	cout << "Yes\n";

	for( auto i : ord )
	{
		if( !used[i] )
		{
			if( dp[i] == 3 ) dfs2(i, 1);
			else dfs2(i, dp[i]);
		}
	}
	for( int v = 2; v <= n; v ++ )
	{
		if( dp[v] == 1 ) cnt[v] ++, g2[par[v]].push_back(v);
		else cnt[par[v]] ++, g2[v].push_back(par[v]);
	}
	queue <int> q;

	for( int i = 1; i <= n; i ++ )
	{
		if( cnt[i] == 0 ) q.push(i);
	}
	while( !q.empty() )
	{
		int v = q.front();
		q.pop(); cout << v << ' ';

		for( auto to : g2[v] )
		{
			cnt[to] --;
			if( !cnt[to] ) q.push(to);
		}
	}
	cout << '\n';
}
int main()
{
	ios_base::sync_with_stdio(0);

	int t; cin >> t;
	while(t --) solve();
}
